//! Fuse-for-fuse conformance with the vendor fitters on synthetic designs.
//!
//! `tests/vectors/<family>/<name>.tt2` are synthetic designs generated by `tools/fuzzers/fitter-macrocell/exp_feat.py`;
//! `<name>.jed` holds the fuses the vendor fitter (fit150x 1.8.7.8) chose for them, rewritten in our
//! own JEDEC layout (`examples/jed_rewrite.rs`), and `<name>.args` the vendor command-line arguments.
use atf15xx_arch::Family;
use std::path::PathBuf;

#[test]
fn vendor_identical_fuses() {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/vectors");
    let (mut ok, mut bad) = (0, vec![]);
    for fam in Family::ALL {
        let dir = root.join(fam.number());
        let mut names: Vec<PathBuf> =
            std::fs::read_dir(&dir).unwrap().map(|e| e.unwrap().path()).filter(|p| p.extension().map_or(false, |e| e == "tt2")).collect();
        names.sort();
        for tt2 in names {
            let stem = tt2.file_stem().unwrap().to_string_lossy().to_string();
            let tmp = std::env::temp_dir().join(format!("atf15xx-fit-test-{}-{stem}", std::process::id()));
            std::fs::create_dir_all(&tmp).unwrap();
            let input = tmp.join(format!("{stem}.tt2"));
            std::fs::copy(&tt2, &input).unwrap();
            let args_text = std::fs::read_to_string(tt2.with_extension("args")).unwrap();
            let mut args = vec![input.to_string_lossy().to_string()];
            args.extend(args_text.split_whitespace().map(String::from));
            let res = atf15xx_fit::cli::run(fam, &args);
            let got = std::fs::read_to_string(tmp.join(format!("{stem}.jed"))).ok();
            let want = atf15xx_fit::jed::parse(&std::fs::read_to_string(tt2.with_extension("jed")).unwrap()).unwrap();
            let _ = std::fs::remove_dir_all(&tmp);
            let got = got.as_deref().map(|t| (atf15xx_fit::jed::parse(t), t.contains(&format!("C{:04X}*", want.checksum()))));
            match (res, got) {
                (Ok(()), Some((Ok(fz), true))) if fz == want => ok += 1,
                (res, got) => bad.push(format!("{}/{stem}: {:?} {:?}", fam.number(), res.err(), got.map(|g| g.1))),
            }
        }
    }
    assert!(bad.is_empty(), "{ok} identical, {} different:\n{}", bad.len(), bad.join("\n"));
    assert!(ok > 90);
}

#[test]
fn decode_vendor_jed() {
    use atf15xx_arch::decode::*;
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/vectors/1504");
    let name = std::fs::read_dir(&root)
        .unwrap()
        .map(|e| e.unwrap().path())
        .find(|p| p.to_string_lossy().contains("dff_g1_") && p.extension().map_or(false, |e| e == "jed"))
        .unwrap();
    let fz = atf15xx_fit::jed::parse(&String::from_utf8_lossy(&std::fs::read(&name).unwrap())).unwrap();
    let d = decode(Family::F1504, &fz.bits);
    // vendor dff_g1 designs: Y.D = A clocked by GCLK1, always-enabled pin output
    let y: Vec<&MacrocellConfig> =
        d.macrocells.iter().filter(|m| m.storage == Storage::DFlipFlop && m.output == Tap::Reg && m.uses_pts()).collect();
    assert_eq!(y.len(), 1);
    assert_eq!(y[0].clock, ClockSource::Global(1));
    assert_eq!(y[0].oe, OutputEnable::Always);
    assert_eq!(y[0].pt_use[0], PtUse::Sum);
    assert!(d.jtag);
}
